int LLVMFuzzerInitialize(int *argc, char ***argv) {
        core_register_options();
        fe_common_core_register_options();
        char *irssi_argv[] = {*argv[0], "--home", "/tmp/irssi", NULL};
        int irssi_argc = sizeof(irssi_argv) / sizeof(char *) - 1;
